#include <psx/non_normal/client.hpp>
namespace psx::non_normal {
bool Client::connect(const std::wstring& endpoint,ProcessIdentity expected)noexcept {disconnect();pipe_=CreateFileW(endpoint.c_str(),GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_EXISTING,FILE_FLAG_OVERLAPPED|SECURITY_SQOS_PRESENT|SECURITY_IDENTIFICATION,nullptr);if(pipe_==INVALID_HANDLE_VALUE)return false;if(!authenticate(pipe_,false,expected,server_)||!(session_=nonce())){disconnect();return false;}return true;}
void Client::disconnect()noexcept{if(pipe_!=INVALID_HANDLE_VALUE)CloseHandle(pipe_);pipe_=INVALID_HANDLE_VALUE;server_={};session_=0;outgoing_=incoming_=0;wire_version_=0;request_counter_=0;}
bool Client::send(Request r,std::uint32_t timeout)noexcept {if(!is_connected())return false;if(wire_version_&&wire_version_!=r.wire_version){disconnect();return false;}wire_version_=r.wire_version;r.client=current_process();r.target=server_;r.session=session_;r.frequency=qpc_frequency();if(!r.issued_qpc)r.issued_qpc=qpc();if(!r.deadline_qpc)r.deadline_qpc=r.issued_qpc+static_cast<std::int64_t>(r.frequency*5);if(!r.originator.pid){r.originator=r.client;r.originator_session=session_;}Frame f;if(outgoing_==UINT32_MAX||!encode(r,++outgoing_,f)||!write_frame(pipe_,f,timeout)){disconnect();return false;}return true;}
bool Client::receive(Result& r,std::uint32_t timeout)noexcept {if(!is_connected())return false;Frame f;if(!read_frame(pipe_,f,timeout)){if(GetLastError()!=ERROR_NO_DATA)disconnect();return false;}std::uint32_t seq{};if(!decode({f.bytes.data(),f.size},r,seq)||r.wire_version!=wire_version_||seq<=incoming_||r.server!=server_||r.session!=session_){disconnect();return false;}incoming_=seq;return true;}
bool Client::transact(Request r,Result& result,std::uint32_t timeout)noexcept {const auto end=GetTickCount64()+timeout;if(!send(r,timeout))return false;for(;;){if(receive(result,0)&&result.request==r.request&&result.command==r.command)return true;if(!is_connected())return false;const auto now=GetTickCount64();if(now>=end)return false;Sleep(static_cast<DWORD>((end-now)<2?(end-now):2));}}
}
